-- Rellena la columna Solucion (base de conocimiento sintética)
UPDATE Incidencias SET Solucion = CASE Titulo
  WHEN N'Mi pantalla parpadea' THEN N'1) Cambiar la frecuencia de actualización a 60 Hz en Configuración > Pantalla > Opciones avanzadas. 2) Probar con otro cable de vídeo. 3) Actualizar el controlador gráfico. Si persiste, sustituir el monitor.'
  WHEN N'No puedo acceder a la VPN' THEN N'1) Comprobar que la hora del equipo y del token están sincronizadas. 2) Reinstalar o reiniciar el cliente Cisco. 3) Probar otra red (la de casa puede bloquear el puerto). Si persiste, IT revisa el perfil VPN.'
  WHEN N'Ratón no funciona' THEN N'1) Probar el ratón en otro equipo. 2) Reconectar el receptor USB o reemparejarlo. 3) Reinstalar el controlador en el Administrador de dispositivos. Si falla en otro equipo, sustituirlo.'
  WHEN N'Olvido de contraseña' THEN N'Restablecer la contraseña desde el portal de autoservicio o solicitar a IT el desbloqueo de la cuenta y una contraseña temporal que se cambiará en el primer inicio de sesión.'
  WHEN N'Impresora atasca papel' THEN N'1) Apagar y retirar el papel atascado con cuidado. 2) Revisar rodillos y bandeja (papel húmedo o mal colocado). 3) El ruido de engranajes indica avería: avisar al servicio técnico de la impresora.'
  WHEN N'Lentitud extrema en el PC' THEN N'1) Reiniciar y revisar en el Administrador de tareas qué proceso consume CPU/disco. 2) Desactivar programas de inicio innecesarios. 3) Si empezó tras una actualización, desinstalar la última actualización. 4) Comprobar el estado del disco.'
  WHEN N'Correo no sincroniza' THEN N'1) Quitar la cuenta de Outlook en el móvil y volver a añadirla. 2) Actualizar la app. 3) Comprobar que no haya cambiado la contraseña de la cuenta. 4) Verificar la sincronización en segundo plano.'
  WHEN N'Carpeta compartida inaccesible' THEN N'Los permisos se gestionan por grupo de seguridad. Comprobar si el usuario sigue en el grupo de Finanzas; si no, el responsable del área debe solicitar su alta a IT.'
  WHEN N'Error en ERP' THEN N'1) Ejecutar el ERP como administrador. 2) Revisar el Visor de eventos de Windows para ver el fallo de la aplicación. 3) Reinstalar o reparar el cliente. Si es solo en ese informe, escalar al proveedor del ERP.'
  WHEN N'Teclado mojado' THEN N'1) Desconectar el teclado y secarlo boca abajo. 2) No usarlo hasta que esté seco por completo (24 h). 3) Si las teclas siguen pegajosas, sustituirlo por uno nuevo.'
  WHEN N'Pantalla azul' THEN N'1) Reiniciar en modo seguro. 2) Revertir controladores o actualizaciones recientes. 3) Ejecutar sfc /scannow y comprobar la RAM. El código SYSTEM_SERVICE_EXCEPTION suele deberse a controladores defectuosos.'
  WHEN N'Falta software' THEN N'Instalar software requiere privilegios de administrador. IT debe instalarlo o autorizar la instalación; hay que abrir una solicitud indicando versión y justificación de la licencia.'
  WHEN N'Auriculares rotos' THEN N'1) Seleccionar el micrófono de los auriculares como dispositivo de entrada en Windows y en Teams. 2) Probar los auriculares en otro equipo. 3) Si el zumbido persiste, sustituirlos.'
  WHEN N'Red WiFi inestable' THEN N'1) Reiniciar el punto de acceso de la sala. 2) Comprobar interferencias y saturación del canal. 3) Si hay muchas desconexiones, IT debe revisar el AP o añadir cobertura.'
  WHEN N'Phishing sospechoso' THEN N'No pulsar el enlace ni responder. Reportar el correo con el botón de phishing, eliminarlo y avisar a Seguridad. Si se pulsó el enlace, cambiar la contraseña de inmediato.'
  WHEN N'Monitor adicional no enciende' THEN N'1) Comprobar el cable de alimentación y la regleta. 2) Probar otra toma o cable. 3) Si el LED sigue apagado, el monitor o su fuente están averiados y hay que sustituirlo.'
  WHEN N'Error al guardar PDF' THEN N'1) Actualizar Adobe Acrobat Reader. 2) Usar Archivo > Guardar como en una ruta local. 3) Reparar la instalación desde Ayuda > Reparar instalación.'
  WHEN N'Certificado caducado' THEN N'El certificado digital debe renovarse en la entidad emisora (por ejemplo, FNMT) y después instalarse en el navegador y en el almacén de Windows. IT puede ayudar con la instalación.'
  WHEN N'Disco duro lleno' THEN N'1) Ejecutar el Liberador de espacio y Almacenamiento > Archivos temporales. 2) Vaciar la papelera y revisar Descargas. 3) Mover datos pesados a OneDrive o a un disco externo.'
  WHEN N'No llegan los correos externos' THEN N'IT debe revisar los registros MX, el filtro antispam y las reglas de transporte del servidor de correo, y comprobar que el buzón no está lleno ni bloqueado.'
  WHEN N'Actualización atascada' THEN N'1) Esperar hasta 3 horas. 2) Si no avanza, apagar manteniendo el botón de encendido y reiniciar. 3) Si vuelve a bloquearse, arrancar en modo de recuperación y restaurar el sistema.'
  WHEN N'Doble autenticación falla' THEN N'1) Sincronizar la hora del móvil (automática). 2) Volver a registrar la cuenta en Authenticator. 3) Si no funciona, IT restablece el método de doble factor.'
  WHEN N'Ratón va a saltos' THEN N'1) Limpiar el sensor óptico y la almohadilla. 2) Probar sobre otra superficie no brillante. 3) Si continúa, probar otro ratón o sustituirlo.'
  WHEN N'Fallo en cámara web' THEN N'1) Comprobar permisos de cámara en Configuración > Privacidad. 2) Actualizar o reinstalar el controlador. 3) Probar la cámara en otra app. Si sigue en negro, es un fallo de hardware.'
  WHEN N'Falta de licencias' THEN N'1) Cerrar sesión y volver a iniciar sesión en Office con la cuenta corporativa. 2) Comprobar que el usuario tiene licencia asignada. 3) Si no, IT debe asignarle una desde el panel de administración.'
  WHEN N'Docking station no va' THEN N'1) Desconectar y reconectar el dock y su alimentación. 2) Probar otro cable USB-C que admita vídeo y carga. 3) Actualizar firmware y controladores del dock.'
  WHEN N'Archivo de Excel dañado' THEN N'1) Abrir con Archivo > Abrir > Abrir y reparar. 2) Recuperar una versión anterior desde el historial de versiones de OneDrive/SharePoint o el servidor. 3) Pedir restaurar copia de seguridad a IT.'
  WHEN N'Intranet muy lenta' THEN N'El problema afecta solo a la intranet, no a internet. IT debe revisar la carga del servidor web y la base de datos de la intranet. El usuario puede borrar la caché del navegador.'
  WHEN N'Cambio de tóner' THEN N'El material se solicita a Compras o Servicios Generales. Abrir una petición indicando modelo de impresora y color de tóner.'
  WHEN N'Cifrado BitLocker' THEN N'La clave de recuperación de 48 dígitos está asociada a la cuenta corporativa. IT la obtiene del directorio o de Entra ID tras verificar la identidad del usuario.'
  WHEN N'OneDrive no sincroniza' THEN N'1) Resolver los conflictos manualmente, conservando la versión correcta. 2) Cerrar los archivos abiertos. 3) Restablecer OneDrive con wsreset o desvinculando y volviendo a vincular la cuenta.'
  WHEN N'Teclas intercambiadas' THEN N'Se ha cambiado la distribución del teclado. En Configuración > Hora e idioma > Idioma y región, seleccionar Español (España) como teclado. Alternativa: Windows + Espacio.'
  WHEN N'Ruido de ventilador' THEN N'1) Limpiar las rejillas con aire comprimido. 2) Comprobar procesos que consumen CPU. 3) Si sigue sobrecalentándose, hay que cambiar la pasta térmica o el ventilador (servicio técnico).'
  WHEN N'Baja del sistema' THEN N'Seguir el procedimiento de baja: deshabilitar cuentas, retirar accesos y licencias, redirigir el correo al responsable y recuperar el equipo. La petición debe venir de RRHH o del responsable.'
  WHEN N'SPAM constante' THEN N'1) Marcar los mensajes como correo no deseado. 2) Bloquear los remitentes. 3) IT debe ajustar las reglas del filtro antispam del servidor.'
  WHEN N'Corte en videollamada' THEN N'1) Actualizar Teams. 2) Limpiar la caché de Teams. 3) Desactivar la aceleración por hardware de GPU en la configuración de Teams. 4) Reinstalar si continúa.'
  WHEN N'No puedo imprimir en color' THEN N'En el cuadro de impresión, abrir Propiedades de la impresora y seleccionar Color. Revisar también la impresora predeterminada y que no esté marcada la opción de escala de grises.'
  WHEN N'Bloqueo de web legítima' THEN N'El bloqueo lo aplica el firewall. Hay que solicitar a IT/Seguridad que revise la categoría de la web y la añada a la lista de permitidos si es legítima.'
  WHEN N'Batería no dura' THEN N'1) Ver el informe de batería con powercfg /batteryreport. 2) Si la capacidad es baja, la batería está degradada y hay que sustituirla. 3) Mientras tanto, activar el modo de ahorro de energía.'
  WHEN N'Carpeta desaparecida' THEN N'1) Buscar la carpeta en el Explorador y en OneDrive. 2) Restaurar desde la Papelera de reciclaje de OneDrive o desde Versiones anteriores. 3) Pedir a IT recuperar copia de seguridad.'
  WHEN N'Error de macro en Excel' THEN N'El error 9 indica un índice fuera de rango. Revisar referencias a hojas o libros y habilitar las macros en el Centro de confianza. Si falló tras actualizar Office, revertir la actualización o corregir el código VBA.'
  WHEN N'Teléfono IP no funciona' THEN N'1) Comprobar el cable de red y de alimentación PoE. 2) Reiniciar el teléfono. 3) Si sigue apagado, IT debe revisar el puerto del switch o sustituir el aparato.'
  WHEN N'No reconoce USB' THEN N'1) Probar otro puerto y otro equipo. 2) Administración de discos: asignar letra a la unidad. 3) Reinstalar el controlador USB. Si no aparece, el pendrive está dañado.'
  WHEN N'Restablecer perfil' THEN N'Crear un perfil de usuario nuevo, copiar los datos del perfil antiguo y borrar el dañado. Antes probar sfc /scannow para reparar archivos del sistema.'
  WHEN N'Aviso de virus' THEN N'1) No abrir el archivo. 2) Revisar el historial de protección de Defender y ejecutar un análisis completo. 3) Avisar a Seguridad para que valide la amenaza.'
  WHEN N'Pérdida de favoritos' THEN N'1) Comprobar si Chrome inició sesión con otra cuenta o perfil. 2) Restaurar desde la sincronización de la cuenta. 3) Si hay perfil corrupto, recuperar la copia del archivo Bookmarks.'
  WHEN N'Solicitud de monitor' THEN N'Solicitud de equipamiento por recomendación médica. Abrir petición a Compras con el informe de prevención de riesgos laborales para su aprobación.'
  WHEN N'Software contable no abre' THEN N'Si solo afecta a un usuario, borrar la caché local y reinstalar el cliente. Comprobar también conexión al servidor y permisos del usuario.'
  WHEN N'Cables sueltos' THEN N'Solicitud a Mantenimiento: organizar y canalizar los cables con bridas o canaletas. No requiere intervención técnica de IT.'
  WHEN N'Archivos de solo lectura' THEN N'1) Comprobar los permisos de la carpeta del servidor. 2) Ver si hay un archivo de bloqueo temporal (~$) que impide editarlo. 3) Si persiste, IT revisa los permisos NTFS.'
  WHEN N'Ping alto' THEN N'1) Probar con cable en lugar de WiFi. 2) Ejecutar traceroute para ver dónde aumenta la latencia. 3) Si hay VPN, probar otro servidor. Escalar a Redes con el resultado.'
  WHEN N'Altavoces sin sonido' THEN N'1) Seleccionar el dispositivo de salida correcto (altavoces del monitor) en Windows. 2) Comprobar que el monitor reciba audio por HDMI/DisplayPort y no esté silenciado. 3) Reinstalar el controlador de audio.'
  WHEN N'Correo borrado por error' THEN N'1) Revisar Elementos recuperables en Outlook. 2) Si está vacío, solicitar a IT restaurar el buzón desde copia de seguridad, que depende del periodo de retención.'
  WHEN N'App bloqueada' THEN N'El bloqueo lo aplica una directiva corporativa (AppLocker). Si la app es necesaria, solicitar a IT una excepción.'
  WHEN N'Cambio de departamento' THEN N'Solicitud de movimiento interno: RRHH o el responsable pide a IT cambiar los grupos de seguridad y listas de distribución, y retirar los permisos del departamento anterior.'
  WHEN N'Sincronización de contactos' THEN N'1) Comprobar que los contactos se guardan en la cuenta de Exchange y no en local. 2) Activar la sincronización de contactos en la app del móvil. 3) Quitar y volver a añadir la cuenta.'
  WHEN N'Mensaje de almacenamiento' THEN N'1) Vaciar Elementos eliminados y archivar correos antiguos. 2) Guardar adjuntos grandes fuera del correo. 3) Si es necesario, IT puede ampliar la cuota.'
  WHEN N'Proyector no enfoca' THEN N'El anillo de enfoque está atascado mecánicamente. Hay que revisarlo por el servicio técnico o sustituir el proyector. No forzar la rueda.'
  WHEN N'Acceso a base de datos' THEN N'Solicitud de acceso a producción: requiere aprobación del responsable de datos y un usuario de solo lectura creado por el DBA con justificación y caducidad.'
  WHEN N'Error de formato' THEN N'1) En Word, seleccionar el texto > Revisión > Idioma y fijar Español (España). 2) Desmarcar Detectar idioma automáticamente. 3) Establecerlo como predeterminado.'
  WHEN N'Cable de red roto' THEN N'Sustituir el cable Ethernet por uno nuevo. Pedirlo a IT o Compras.'
  WHEN N'Sesión caducada VPN' THEN N'El cierre cada hora lo causa una política de la VPN (tiempo de sesión). IT puede ampliar el tiempo en la puerta de enlace Palo Alto o activar la reconexión automática.'
  WHEN N'Resolución de pantalla' THEN N'1) Actualizar el controlador gráfico. 2) Configuración > Pantalla > fijar 1920x1080. 3) Si no aparece, comprobar el cable. Una directiva corporativa también puede forzar la resolución.'
  WHEN N'No puedo descomprimir ZIP' THEN N'El archivo está corrupto o incompleto. Pedir al proveedor que lo reenvíe y probar con otra herramienta de descompresión.'
  WHEN N'Firma electrónica' THEN N'Instalar AutoFirma desde la web oficial, importar el certificado en el navegador y comprobar el funcionamiento en la sede electrónica de pruebas. IT puede asistir con la instalación.'
  WHEN N'Actualización de RAM' THEN N'Ampliación de hardware: abrir solicitud a IT con justificación del proyecto. Se valora la compatibilidad del portátil y el coste.'
  WHEN N'Ratón con doble clic' THEN N'1) Ajustar la velocidad del doble clic en Configuración del ratón. 2) Probar otro ratón. 3) Si es el microinterruptor desgastado, sustituir el ratón.'
  WHEN N'Redirección de correo' THEN N'IT configura una regla de reenvío del buzón al compañero indicado (o delegación y respuesta automática) para el periodo de baja. La solicita el responsable.'
  WHEN N'Página en blanco' THEN N'1) Probar otro navegador o modo incógnito. 2) Borrar la caché y cookies. 3) Si ocurre solo con una ficha, es un error de datos del CRM: reportarlo al administrador.'
  WHEN N'Teams muy pesado' THEN N'1) Actualizar a la nueva versión de Teams. 2) Borrar la caché. 3) Cerrar pestañas y reducir efectos de vídeo. 4) Si falta RAM, valorar ampliación.'
  WHEN N'Crear grupo' THEN N'IT crea el grupo de distribución con el nombre solicitado y asigna al solicitante como propietario. Debe aprobarlo el responsable del área.'
  WHEN N'Letras del teclado borradas' THEN N'Solicitar cambio del teclado del portátil a IT. Mientras tanto, usar un teclado USB externo.'
  WHEN N'Error de inicio de sesión' THEN N'1) Comprobar que el equipo está conectado a la red corporativa o VPN. 2) Reiniciar. 3) Iniciar con credenciales en caché. Si no, IT revisa el servicio RPC y el dominio.'
  WHEN N'Fallo escáner' THEN N'1) Comprobar que la ruta SMB y las credenciales del usuario en la impresora son correctos. 2) Verificar permisos de escritura en la carpeta compartida. 3) Probar con otro destino.'
  WHEN N'PC no da señal' THEN N'1) Comprobar cable de vídeo y entrada del monitor. 2) Reasentar la RAM y la tarjeta gráfica. 3) Conectar a la salida de la gráfica dedicada, no a la placa. Si sigue sin señal, revisión de hardware.'
  WHEN N'Renovar licencia' THEN N'La renovación de licencias la gestiona IT con Compras. Abrir petición antes de la caducidad indicando el producto y la fecha.'
  WHEN N'Conexión a base de datos' THEN N'Access denied indica credenciales o permisos incorrectos. Comprobar el usuario y host en MySQL, y que el conector esté instalado. Si es necesario, el administrador crea o corrige los permisos.'
  WHEN N'Iconos desaparecidos' THEN N'Clic derecho en el escritorio > Ver > marcar Mostrar iconos del escritorio. Si no, reiniciar el Explorador de Windows desde el Administrador de tareas.'
  WHEN N'Auricular Bluetooth' THEN N'1) Desemparejar y volver a emparejar. 2) Actualizar firmware y controlador Bluetooth. 3) Desactivar el ahorro de energía del adaptador Bluetooth.'
  WHEN N'Mac muy caliente' THEN N'1) Ver en Monitor de actividad qué proceso consume CPU. 2) Reiniciar y actualizar macOS. 3) Reiniciar SMC. Si la batería dura 2 horas, valorar su sustitución.'
  WHEN N'Cinta de opciones Excel' THEN N'Pulsar Ctrl+F1 o hacer doble clic en una pestaña para volver a mostrar la cinta. Si no, Archivo > Opciones > Personalizar cinta > Restablecer.'
  WHEN N'Carpetas vacías' THEN N'1) Reconectar la unidad de red. 2) Comprobar permisos de listado. 3) Puede ser un problema de caché de sin conexión: desactivar archivos sin conexión. Si persiste, IT revisa el servidor.'
  WHEN N'Página lenta' THEN N'Es un problema de la aplicación web de gastos. Reportarlo a su administrador, ya que no depende del equipo del usuario. Probar a subir recibos más pequeños.'
  WHEN N'Instalar Python' THEN N'Solicitar permisos temporales de administrador a IT, con aprobación del responsable, o instalar Python en el perfil de usuario con el instalador sin privilegios.'
  WHEN N'Error de disco' THEN N'S.M.A.R.T. Status Bad significa fallo inminente del disco. Hacer copia de seguridad inmediata de los datos y solicitar a IT sustituir el disco.'
  WHEN N'Mensaje de advertencia' THEN N'NET::ERR_CERT_INVALID indica un certificado web no válido. No aceptar la excepción: avisar al responsable de la herramienta para que renueve el certificado.'
  WHEN N'Reinstalación SO' THEN N'Hacer copia de seguridad de los datos y solicitar a IT el reformateo con la imagen corporativa. Comprobar antes el hardware del disco y la RAM.'
  WHEN N'Filtro en Excel' THEN N'Datos > Borrar filtro, o Ctrl+Mayús+L para desactivar el autofiltro. Si hay filas ocultas, seleccionar todo y mostrar filas.'
  WHEN N'Pérdida de señal WiFi' THEN N'El microondas interfiere con la banda de 2.4 GHz. Conectar a la red de 5 GHz o pedir a IT que ajuste el canal del AP.'
  WHEN N'No me llega MFA' THEN N'1) Comprobar cobertura y que el número del móvil es correcto. 2) Solicitar nuevo SMS o usar un método alternativo. 3) El administrador de Salesforce puede restablecer MFA.'
  WHEN N'Monitorización roja' THEN N'Incidencia crítica de servidor: avisar al equipo de infraestructura, revisar procesos y consultas que saturan la CPU y valorar reiniciar el servicio. No es resoluble por el usuario.'
  WHEN N'Desplazamiento horizontal' THEN N'Ratón con rueda dañada: sustituirlo. Se puede probar a limpiar la rueda y actualizar el controlador, pero normalmente es hardware.'
  WHEN N'Bloqueo cuenta' THEN N'IT desbloquea la cuenta de Active Directory tras verificar la identidad. Se desbloquea sola tras el tiempo configurado en la política.'
  WHEN N'PDF lento' THEN N'1) Actualizar Adobe Reader. 2) Desactivar la mejora del renderizado y limitar el uso de gráficos. 3) Abrir el plano con un visor CAD. Si es muy pesado, optimizarlo.'
  WHEN N'Cable DisplayPort' THEN N'Solicitud de material: pedir a IT/Compras un adaptador o cable activo de DisplayPort a HDMI compatible con el monitor.'
  WHEN N'Añadir a lista' THEN N'IT añade el correo del usuario a la lista de distribución indicada, con aprobación del propietario de la lista.'
  WHEN N'Micrófono interno' THEN N'1) Desactivar las mejoras de audio del micrófono. 2) Bajar el volumen de entrada. 3) Usar auriculares. 4) Activar la cancelación de ruido en Teams.'
  WHEN N'Móvil de empresa roto' THEN N'Solicitar a IT la sustitución del dispositivo. Mientras tanto, hacer copia de seguridad de los datos y no usarlo si la pantalla es peligrosa.'
  WHEN N'App no aparece' THEN N'1) Buscar la app en Inicio > Todas las aplicaciones. 2) Instalarla desde el Portal de empresa. 3) Si se desinstaló por una directiva, IT debe volver a desplegarla.'
  WHEN N'Carpetas duplicadas' THEN N'1) Revisar versiones y conservar la más reciente. 2) Borrar las copias de conflicto. 3) Evitar editar el mismo archivo desde varios equipos a la vez.'
  ELSE Solucion END
WHERE Solucion IS NULL;
GO

-- Unificar estado y forzar revectorización
UPDATE Incidencias SET Estado = 'Abierto' WHERE Estado = 'Abierta';
UPDATE Incidencias SET VectorDescripcion = NULL;
GO